{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence contains no Introduction/rationale text describing the current state of knowledge or uncertainties motivating the review. The only mention of uncertainty appears in Results (text_4) regarding scarce EMS studies, which does not constitute a rationale section."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence explains the importance of or need for conducting the review. The Methods (text_3) describe the protocol and research question but do not articulate why the review was needed."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not mention any existing similar systematic reviews, nor any citation of a previous review being updated or replicated. Without the Introduction text, this cannot be confirmed as reported."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of the psychological impact of exposure to SARS-CoV-2 (an observational/exposure question), not a review of intervention effects, so no mechanism of action of an intervention needs describing."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines associations between pandemic exposure and mental health outcomes, not a complex intervention or delivery context, so a logic model of intervention components is not applicable."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The search began with the formulation of the following research question by R.S.C., whose clinical response was possible, in PIO (Population-Intervention-Outcome) format [46]: 'Has the possible exposure to SARS-CoV-2 during the COVID-19 pandemic (I) affected the mental health (O) of HPs providing health care outside the hospital (P)?",
      "reason": "The review's objective/question is explicitly stated as a research question formulated in a structured framework (PIO), covering population, intervention/exposure, and outcome."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "Has the possible exposure to SARS-CoV-2 during the COVID-19 pandemic (I) affected the mental health (O) of HPs providing health care outside the hospital (P)?",
      "reason": "This is a review of exposure effects (SARS-CoV-2 exposure) on mental health outcomes, not a review of intervention effects with planned comparisons; the authors appropriately used the PIO variant, so PICO comparisons do not apply."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The selected research studies had to meet the following inclusion criteria: (1) being original, (2) based on qualitative and/or quantitative methods, (3) with any methodological design, (4) submitted for peer-review, (5) published in English, Spanish, French, Italian or Portuguese, (6) completed after December 2019, (7) without geographic limitation, (8) with at least the abstract available, and (9) that in their results evaluated the impact of possible exposure to SARS-CoV-2 on levels of stress, anxiety, depression and/or self-efficacy of the HPs who were working in public, private, or voluntary out-of-hospital EMS during the COVID-19 pandemic",
      "reason": "Eligibility criteria are fully specified, linked to the PIO question framework, covering designs, setting (out-of-hospital EMS), outcomes, and population."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "(1) being original, ... (4) submitted for peer-review, (5) published in English, Spanish, French, Italian or Portuguese, (6) completed after December 2019, ... (8) with at least the abstract available",
      "reason": "Report characteristics are specified: publication status (original, peer-reviewed), language restrictions, date restriction (after December 2019), and availability of at least an abstract."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_3",
      "quote": "Opinion articles and editorials, studies of low scientific-technical quality, those that did not reply to the posed research question and/or were not in line with the objective of the review, as well as others that, despite including out-of-hospital HPs, contributed no specific data on this subgroup in their results were excluded.",
      "reason": "The review does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported; exclusion criteria focus on format, quality, relevance, and lack of subgroup data."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": "text_4",
      "quote": "Neither a meta-analysis nor a meta-synthesis could be conducted with the studies included in the review due to the high levels of observed heterogeneity between the participants, in the area of development, in the scales and measurement instruments used, and with the final results. ... Anarrative synthesis of the main characteristics and findings from those studies was performed",
      "reason": "No groups used in the synthesis are specified or linked to comparisons in the objectives; only an unstructured narrative synthesis of study characteristics and findings is reported."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_3",
      "quote": "High methodological quality was established for the inclusion of studies in the review.",
      "reason": "Notable restrictions (e.g., requiring high methodological quality, language limits, abstract availability) are stated without explicit rationales for these restrictions."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_6",
  "elements": [
    {
      "element_id": "prisma_2020_6_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "the electronic version of the following databases were consulted in November 2021",
      "reason": "A single search date (November 2021) is given, but it is stated collectively for all databases rather than for each individual source, and no last-searched date is provided for the grey literature sources or other methods."
    },
    {
      "element_id": "prisma_2020_6_e2",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "CINHAL (EBSCOhost, Ipswich, MA, USA), Cochrane Library, Cuiden, ... Medline (Pubmed, Bethesda, MD, USA), PsycINFO (Ovid, New York, NY, USA), Scopus (Elsevier, New York, NY, USA), and Web of Science-WOS (Elsevier, New York, NY, USA)",
      "reason": "Database names and platforms/interfaces are reported (e.g., EBSCOhost, Ovid, PubMed, Elsevier), but coverage dates for each database are not reported."
    },
    {
      "element_id": "prisma_2020_6_e3",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "The study protocol has previously been registered at the International Prospective Register of Systematic Reviews PROSPERO, supported by the Centre for Reviews and Dissemination of the University of York, under reference CRD-42021259951.",
      "reason": "PROSPERO is named, but it is mentioned as protocol registration rather than as a searched study register, and no date restrictions for registers are reported; the PRISMA flow diagram mentions registers but no register search details or restrictions are given."
    },
    {
      "element_id": "prisma_2020_6_e4",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "a manual inverse search strategy was proposed, reviewing webpages, sources of grey literature (ProQuest Dissertations and Theses Global, and OpenGrey)",
      "reason": "Websites and grey literature sources are mentioned generically (\"webpages\"), and grey literature sources are named, but no specific website names or URLs are reported."
    },
    {
      "element_id": "prisma_2020_6_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "In the face of any doubt or relevant data unavailable in the selected studies, we planned to contact the corresponding author directly, requesting the necessary clarifications.",
      "reason": "Contacting authors was only planned for clarifying data from included studies, not for identifying studies; no organisations or manufacturers were contacted for study identification."
    },
    {
      "element_id": "prisma_2020_6_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "we planned to contact the corresponding author directly",
      "reason": "No individuals were contacted for the purpose of identifying studies; author contact was only planned for clarifying data, so this requirement does not apply."
    },
    {
      "element_id": "prisma_2020_6_e7",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "as well as bibliographic references cited in the selected studies",
      "reason": "The manuscript specifies that reference lists of the selected (included) studies were examined for additional relevant works."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "A total of seven new references were found when completing an inverse manual search.",
      "reason": "Backward citation searching is mentioned (the inverse manual search and reference checking), and the flow diagram shows 'Citation searching (n = 5)', but no citation index/platform used or specific search date for the citation searching is reported."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "the electronic version of the following databases were consulted in November 2021",
      "reason": "No journals or conference proceedings were browsed directly as sources; searches were conducted via bibliographic databases, so this requirement does not apply."
    }
  ],
  "confidence": 82
}

