{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Critical Appraisal Tools from JBI of the University of Adelaide (Australia) [47], considered adequate for the design of the study [48,49], were used to evaluate the scientifictechnical quality of the selected articles as well as to determine the extent to which the risk of bias was reduced or eliminated in their design, performance, and/or analysis.",
      "reason": "The manuscript explicitly names the risk-of-bias/critical appraisal tool used: the JBI Critical Appraisal Tools (University of Adelaide), with references [47-49] indicating specific checklist versions for each study design."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Q1: Were the criteria for inclusion in the sample clearly defined? Q2: Were the study subjects and the setting described in detail? Q3: Was the exposure measured in a valid and reliable way? ... Q10: Do the conclusions drawn in the research report flow from the analysis or interpretation of the data?",
      "reason": "The individual items/domains of the JBI checklists are fully enumerated in the text accompanying Tables 3 and 4: eight items for cross-sectional studies and ten items for qualitative studies."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Each individual study was classified as having a low-, moderate-, or high-risk level of bias based on the number of items answered with 'yes'. For qualitative studies (10 items), the methodological quality was considered low, moderate, or high if three or less, four to seven, or more than eight criteria were met, respectively [48]. For cross-sectional studies (8 items), the methodological quality was considered low, moderate, or high if two or less, moderate if three to five, and high if six to eight criteria were met, respectively [49].",
      "reason": "An overall judgement (low/moderate/high risk of bias) was made and the explicit scoring rules/thresholds for deriving it are reported for each study design."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No adaptations or modifications to the JBI Critical Appraisal Tools are described anywhere in the retrieved evidence; the tools appear to be used as published, but no explicit statement confirms or denies adaptation."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "Critical Appraisal Tools from JBI of the University of Adelaide (Australia) [47] ... were used to evaluate the scientifictechnical quality of the selected articles",
      "reason": "The manuscript reports using existing, published JBI Critical Appraisal Tools; no newly developed risk-of-bias tool was created, so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The final selection of the studies, the evaluation of their methodological quality, and the data-extraction was completed in pairs (N.G.S.B.-H.O.B., J.J.J.A.-J.J.F.D., A.M.R.M.-M.M.O., and M.P.M.H.-A.M.S.), independently with blind reviews, thereby resolving any possible discrepancies through consensus and, in its absence, calling for the participation of a third evaluator (R.M.C.G.).",
      "reason": "The number of reviewers (pairs, with a third evaluator available), their independent and blinded work, and the disagreement-resolution procedure (consensus, then third evaluator R.M.C.G.) are all reported; a pilot concordance test with eight reviewers is also described."
    },
    {
      "element_id": "prisma_2020_11_e7",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "In the face of any doubt or relevant data unavailable in the selected studies, we planned to contact the corresponding author directly, requesting the necessary clarifications.",
      "reason": "A process of contacting corresponding authors for clarifications is described, but it is framed generically for doubts or unavailable data rather than specifically for obtaining or confirming risk-of-bias information from study investigators; the Results (text_4) note it was never needed."
    },
    {
